function fitPreview(host){if(!host.isConnected)return;const frame=host.parentElement;const h=Math.max(host.offsetHeight,35),w=280;const s=Math.min(.94,(frame.clientWidth-24)/w,(frame.clientHeight-26)/h);host.style.transform='translate(-50%,-50%) scale('+s.toFixed(3)+')';}
const resizeObserver='ResizeObserver' in window?new ResizeObserver(entries=>entries.forEach(({target})=>{const host=target.querySelector('.component-host');if(host)fitPreview(host);})):null;
/* Favoritos: los mismos «guardados» de la biblioteca clásica (clave compartida), solo ids conocidos. */
const FAV_KEY='estilos-favs-v1';let favs=[],favExtra=[];const favToTinta=x=>BY_ID[x]?x:BY_ID['lib-'+x]?'lib-'+x:null,favToStored=id=>id.replace(/^lib-/,'');
try{const raw=JSON.parse(localStorage.getItem(FAV_KEY)||'[]');if(Array.isArray(raw)){const clean=[...new Set(raw.map(x=>String(x).replace(/[^\w-]/g,'').slice(0,60)).filter(Boolean))];clean.forEach(x=>{const id=favToTinta(x);if(id)favs.push(id);else favExtra.push(x);});favs=[...new Set(favs)];}}catch(e){favs=[];favExtra=[];}
function saveFavs(){try{localStorage.setItem(FAV_KEY,JSON.stringify([...new Set([...favs.map(favToStored),...favExtra])]));}catch(e){toast('No se pudo guardar el favorito en este navegador.');}}
/* Recientes: los últimos diseños que abriste o elegiste (misma clave que la biblioteca clásica). */
