try{const raw=JSON.parse(localStorage.getItem(RECENT_KEY)||'[]');if(Array.isArray(raw)){const clean=[...new Set(raw.map(x=>String(x).replace(/[^\w-]/g,'').slice(0,60)).filter(Boolean))];clean.forEach(x=>{const id=favToTinta(x);if(id)recents.push(id);else recentExtra.push(x);});recents=[...new Set(recents)].slice(0,RECENT_MAX);}}catch(e){recents=[];recentExtra=[];}
function trackRecent(id){if(!BY_ID[id])return;recents=[id,...recents.filter(x=>x!==id)].slice(0,RECENT_MAX);try{localStorage.setItem(RECENT_KEY,JSON.stringify([...recents.map(favToStored),...recentExtra].slice(0,RECENT_MAX)));}catch(e){/* sin almacenamiento: solo esta sesión */}const c=$('recentCount');if(c)c.textContent=recents.length;}
function paintFav(id){const on=favs.includes(id),b=document.querySelector('.fav-button[data-id="'+id+'"]');if(b){b.setAttribute('aria-pressed',String(on));b.textContent=on?'★':'☆';b.setAttribute('aria-label',(on?'Quitar de favoritos ':'Guardar en favoritos ')+BY_ID[id].name);}const c=$('favCount');if(c)c.textContent=favs.length;}
function toggleFav(id){if(!BY_ID[id])return;const i=favs.indexOf(id);if(i>=0)favs.splice(i,1);else favs.push(id);saveFavs();paintFav(id);if(state.favsOnly)renderGallery();else $('favToggle').setAttribute('aria-pressed',String(state.favsOnly));toast(i>=0?'Quitado de favoritos.':'Guardado en favoritos.');}
function renderGallery(){if(resizeObserver)resizeObserver.disconnect();const query=TintaCatalog.normalize(state.query).trim();const list=CATALOG.filter(b=>(state.filter==='all'||b.role===state.filter)&&(!state.chosenOnly||state.selected.includes(b.id))&&(!state.favsOnly||favs.includes(b.id))&&(!state.recentOnly||recents.includes(b.id))&&(state.source==='all'||(state.source==='mine'?!!b.mine:b.source===state.source))&&(state.module==='all'||b.metadata.module===state.module)&&(state.style==='all'||b.metadata.styles.includes(state.style))&&(state.type==='all'||b.metadata.type===state.type)&&(!state.family||b.metadata.family===state.family)&&(!state.interactive||!!TintaStates.info(b))&&(!query||TintaCatalog.searchable(b).includes(query)));if(state.recentOnly)list.sort((a,b)=>recents.indexOf(a.id)-recents.indexOf(b.id));$('catalogSummary').textContent=list.length+' diseños visibles · '+CATALOG.filter(b=>b.source==='library').length+' de la biblioteca + '+CATALOG.filter(b=>b.source==='new').length+' nuevos. Tu selección se conserva al filtrar.';$('statesFilter').setAttribute('aria-pressed',String(state.interactive));$('statesFilter').textContent=state.interactive?'Mostrando interactivos · Ver todos':'Probar estados interactivos · '+CATALOG.filter(b=>TintaStates.info(b)).length;$('catalogCategory').value=state.filter;$('catalogType').value=state.type;$('clearFamily').hidden=!state.family;const grid=$('gallery');grid.replaceChildren();list.forEach(block=>{const selected=state.selected.includes(block.id),card=document.createElement('article');card.className='gallery-item'+(selected?' chosen':'');card.dataset.id=block.id;const stage=document.createElement('button');stage.className='preview-open';stage.dataset.act='detail';stage.dataset.id=block.id;stage.setAttribute('aria-label','Ampliar '+block.name);const host=makeBlock(block);host.inert=true;stage.appendChild(host);const zoom=document.createElement('span');zoom.className='preview-zoom';zoom.textContent='↗';stage.appendChild(zoom);const meta=document.createElement('div');meta.className='gallery-meta';meta.innerHTML='<div class="gallery-meta-top"><h2>'+esc(block.name)+'</h2><span class="role-tag">'+ROLES[block.role]+' · '+(block.source==='library'?'Biblioteca':'Nuevo')+'</span></div><p>'+esc(block.desc)+'</p><button class="select-button" data-act="select" data-id="'+block.id+'" aria-pressed="'+selected+'" aria-label="'+(selected?'Quitar ':'Elegir ')+esc(block.name)+'"><span>'+(selected?'✓':'＋')+'</span> '+(selected?'Elegido':'Elegir bloque')+'</button>';const star=document.createElement('button');star.className='fav-button';star.dataset.act='fav';star.dataset.id=block.id;star.type='button';card.append(stage,meta,star);grid.appendChild(card);paintFav(block.id);requestAnimationFrame(()=>fitPreview(host));if(resizeObserver)resizeObserver.observe(stage);});$('emptyGallery').hidden=!!list.length;document.querySelectorAll('[data-act=filter]').forEach(b=>{const on=b.dataset.filter===state.filter;b.classList.toggle('on',on);b.setAttribute('aria-pressed',on);});$('chosenToggle').setAttribute('aria-pressed',state.chosenOnly);$('favToggle').setAttribute('aria-pressed',state.favsOnly);$('favCount').textContent=favs.length;$('recentToggle').setAttribute('aria-pressed',state.recentOnly);$('recentCount').textContent=recents.length;$('allCount').textContent=CATALOG.length;renderTray();}
function renderTray(){const n=state.selected.length;$('chosenCount').textContent=n;$('trayCount').textContent=n?n+' bloque'+(n===1?' elegido':'s elegidos'):'Tu selección está vacía';$('trayHint').textContent=n?'Todavía puedes cambiar de idea.':'Elige al menos un bloque para continuar.';$('reviewSelection').disabled=!n;$('clearSelection').disabled=!n;}
function toggle(id){if(!Object.hasOwn(BY_ID,id))return;const index=state.selected.indexOf(id);if(index<0){state.selected.push(id);trackRecent(id);toast('Elegido: '+BY_ID[id].name);}else{state.selected.splice(index,1);if(state.choices[BY_ID[id].role]===id)state.choices[BY_ID[id].role]=null;toast('Bloque quitado de tu selección.');}state.composed=false;save();if(state.page==='explore')renderGallery();if(state.page==='review')renderReview();if(detailId===id)updateDetail();}
function openDetail(id){if(!Object.hasOwn(BY_ID,id))return;detailId=id;trackRecent(id);updateMineButtons();const block=BY_ID[id];$('detailTitle').textContent=block.name;$('detailDescription').textContent=block.desc;$('detailStage').replaceChildren(makeBlock(block));setupStateLab(block);$('detailStyleButton').hidden=!TintaButtonStyle.supports(block);$('detailCardStyleButton').hidden=!TintaCardStyle.supports(block);renderResourceSheet(block);updateDetail();if(!$('detailDialog').open)$('detailDialog').showModal();}
