function renderReview(){renderAgentRecommendation();const panel=$('selectionGroups');panel.replaceChildren();$('briefRecap').innerHTML='<span>TU IDEA</span>'+esc(state.brief||'Explorar y combinar mis propios bloques.');$('reviewCount').textContent=state.selected.length+' seleccionados';Object.entries(ROLES).forEach(([role,label])=>{const ids=idsFor(role);if(!ids.length&&!['header','cards','actions','nav'].includes(role))return;const section=document.createElement('section');section.className='selection-group';const h=document.createElement('h3');h.textContent=label;section.appendChild(h);if(!ids.length){const p=document.createElement('p');p.className='group-missing';p.textContent='Sin '+label.toLowerCase()+'. Puedes añadir uno desde Explorar.';section.appendChild(p);}if(['header','nav'].includes(role)&&ids.length>1){const p=document.createElement('p');p.className='group-conflict';p.textContent='Elegiste '+ids.length+' opciones. ¿Cuál quieres usar en esta pantalla? Las otras se conservan en tu selección.';section.appendChild(p);}ids.forEach((id,index)=>{const block=BY_ID[id],row=document.createElement('div');row.className='selection-row';row.dataset.id=id;const sw=document.createElement('span');sw.className='selection-swatch';sw.style.background=block.color;sw.style.color=['c-balance','n-dark','a-dark'].includes(id)?'#f2eee0':'#6b5843';sw.textContent=block.glyph;const text=document.createElement('div');text.className='selection-label';text.innerHTML='<b>'+esc(block.name)+'</b><small>'+(['header','nav'].includes(role)&&ids.length>1?(resolved(role)===id?'En tu pantalla':'Alternativa guardada'):'En tu pantalla')+'</small>';row.append(sw,text);if(['header','nav'].includes(role)&&ids.length>1){const lab=document.createElement('label'),input=document.createElement('input');input.type='radio';input.name='choice-'+role;input.value=id;input.checked=resolved(role)===id;input.dataset.choice=role;lab.append(input,document.createTextNode('Usar'));row.appendChild(lab);}if(!['header','nav'].includes(role)&&ids.length>1){const arrows=document.createElement('div');arrows.className='row-arrows';arrows.innerHTML='<button data-act="move" data-id="'+id+'" data-dir="-1" aria-label="Subir '+esc(block.name)+'" '+(!index?'disabled':'')+'>↑</button><button data-act="move" data-id="'+id+'" data-dir="1" aria-label="Bajar '+esc(block.name)+'" '+(index===ids.length-1?'disabled':'')+'>↓</button>';row.appendChild(arrows);}const edit=document.createElement('button');edit.className='edit-choice';edit.dataset.act='edit-text';edit.dataset.id=id;edit.setAttribute('aria-label','Editar textos de '+block.name);edit.textContent='Texto';edit.disabled=!contentModel(block).fields.length;const editors=document.createElement('div');editors.className='row-editors';editors.appendChild(edit);row.appendChild(editors);const media=document.createElement('button');media.className='edit-choice media-choice';media.dataset.act='edit-media';media.dataset.id=id;media.textContent='Foto / enlace';media.setAttribute('aria-label','Imágenes y destinos de '+block.name);editors.appendChild(media);if(TintaCardStyle.supports(block)){const style=document.createElement('button');style.className='edit-choice';style.dataset.act='card-style';style.dataset.id=id;style.textContent='Diseño / estilo';style.setAttribute('aria-label','Diseño de la tarjeta '+block.name);editors.appendChild(style);}if(TintaButtonStyle.supports(block)){const style=document.createElement('button');style.className='edit-choice';style.dataset.act='button-style';style.dataset.id=id;style.textContent='Color / estilo';style.setAttribute('aria-label','Color y estilo de '+block.name);editors.appendChild(style);}if(role==='cards'){const rep=document.createElement('label');rep.className='repeat-choice';rep.append(document.createTextNode('Copias '));const sel=document.createElement('select');sel.dataset.repeat=id;sel.setAttribute('aria-label','Cuántas copias de '+block.name+' con contenido distinto');for(let n=1;n<=MAX_REPEAT;n++){const o=document.createElement('option');o.value=n;o.textContent=n===1?'1 (solo esta)':n;if((state.repeat[id]||1)===n)o.selected=true;sel.appendChild(o);}rep.appendChild(sel);editors.appendChild(rep);}const remove=document.createElement('button');remove.className='remove-choice';remove.dataset.act='select';remove.dataset.id=id;remove.setAttribute('aria-label','Quitar '+block.name);remove.textContent='×';row.appendChild(remove);section.appendChild(row);});panel.appendChild(section);});const missing=conflicts();$('conflictNotice').hidden=!missing.length;$('conflictNotice').textContent=missing.length?'Antes de crear, elige qué '+missing.map(r=>ROLES[r].toLowerCase()).join(' y ')+' quieres usar.':'';$('composeButton').disabled=!state.selected.length||!!missing.length;$('composeButton').innerHTML=(state.composed?'Volver a componer':'Crear mi pantalla')+' <span>↗</span>';$('resultActions').hidden=!state.composed;$('previewStatus').textContent=state.composed?'TU PANTALLA, COMPUESTA':'VISTA DE TUS BLOQUES';$('previewCaption').textContent=state.composed?finalIds().length+' bloques compuestos. Ninguna elección cambiada al azar.':'Una composición de prueba, hecha con tus elecciones.';renderPhone();}
/* Repetir una tarjeta con sentido: la tarjeta es un ESTILO; cada copia lleva contenido distinto del sector de tu idea. */
const MAX_REPEAT=6;
function repeatCount(id){const n=state.repeat[id]||1;return BY_ID[id]&&BY_ID[id].role==='cards'&&n>1&&TintaSectors.detect(state.brief)?Math.min(n,MAX_REPEAT):1;}
function copyValues(id,i,sectorId){if(!sectorId&&i===0&&state.content[id])return undefined;const sector=sectorId?{id:sectorId}:TintaSectors.detect(state.brief);if(!sector)return undefined;const fields=contentModel(BY_ID[id]).fields,out=TintaSectors.fill(sector.id,fields,{offset:i*2,role:BY_ID[id].role==='header'?'header':undefined});return out?out.map((v,j)=>(v||fields[j].value).slice(0,500)):undefined;}
function blockCopies(id){const n=repeatCount(id);return Array.from({length:n},(_,i)=>n>1?copyValues(id,i):undefined);}
/* Plantillas completas: previa con los bloques reales y contenido del sector; «Usar» las carga (se puede deshacer). */
function templatePreview(t){const frame=document.createElement('div');frame.className='template-frame';const screen=document.createElement('div');screen.className='template-screen';const body=document.createElement('div');body.className='template-body';let dock=null;t.blocks.forEach(b=>{if(BY_ID[b.id].role==='nav'){dock=makeBlock(BY_ID[b.id],{mode:'default',variant:'original',hideSelect:true},null,null);dock.classList.add('template-dock');return;}Array.from({length:b.repeat||1},(_,i)=>i).forEach(i=>body.appendChild(makeBlock(BY_ID[b.id],{mode:'default',variant:'original',hideSelect:true},null,null,copyValues(b.id,i,t.sector))));});screen.appendChild(body);if(dock)screen.appendChild(dock);frame.appendChild(screen);if(window.ResizeObserver)new ResizeObserver(()=>{screen.style.transform='scale('+(frame.clientWidth/390)+')';}).observe(frame);return frame;}
function renderTemplates(){const row=$('templateRow');if(!row||row.dataset.ready)return;row.dataset.ready='1';TintaTemplates.LIST.forEach(t=>{if(TintaTemplates.problems(t,BY_ID).length)return;const card=document.createElement('article');card.className='template-card';card.dataset.id=t.id;const h=document.createElement('h3');h.textContent=t.name;const p=document.createElement('p');p.textContent=t.desc;const btn=document.createElement('button');btn.className='button dark';btn.type='button';btn.dataset.act='use-template';btn.dataset.id=t.id;btn.textContent='Usar esta plantilla';btn.setAttribute('aria-label','Usar la plantilla '+t.name);card.append(templatePreview(t),h,p,btn);row.appendChild(card);});}
function useTemplate(id){const t=TintaTemplates.get(id);if(!t||TintaTemplates.problems(t,BY_ID).length)return;state.selected=t.blocks.map(b=>b.id);state.choices={header:t.blocks.find(b=>BY_ID[b.id].role==='header').id,nav:t.blocks.find(b=>BY_ID[b.id].role==='nav').id};state.repeat={};t.blocks.forEach(b=>{if(b.repeat>1)state.repeat[b.id]=b.repeat;});state.content={};state.assets={};state.ui={};state.buttonStyles={};state.cardStyles={};const det=TintaSectors.detect(state.brief);if(!det||det.id!==t.sector){state.brief=t.brief;$('idea').value=state.brief;}t.blocks.forEach(b=>{const role=BY_ID[b.id].role;if(role==='nav'||b.repeat>1)return;const fields=contentModel(BY_ID[b.id]).fields,out=TintaSectors.fill(t.sector,fields,{offset:0,role:role==='header'?'header':undefined});if(out&&out.some(v=>v))state.content[b.id]=out.map((v,i)=>(v||fields[i].value).slice(0,500));});state.multi=true;screenView='inicio';state.composed=false;save('Usar plantilla «'+t.name+'»');go('review');toast('Plantilla «'+t.name+'» aplicada. Puedes deshacer con Ctrl+Z.');}
/* Animaciones: la biblioteca las muestra en vivo; «Usar» las aplica a la pantalla y a la exportación. */
function renderMotion(){const row=$('motionRow');if(!row||row.dataset.ready)return;row.dataset.ready='1';TintaMotion.LIST.forEach(m=>{const card=document.createElement('article');card.className='motion-card';card.dataset.id=m.id;const demo=document.createElement('div');demo.className='motion-demo';const box=document.createElement('div');box.className='motion-box';box.setAttribute('data-m-'+m.kind,m.id);box.setAttribute('aria-hidden','true');demo.appendChild(box);const kind=document.createElement('span');kind.className='role-tag';kind.textContent=TintaMotion.KINDS[m.kind];const h=document.createElement('h3');h.textContent=m.name;const p=document.createElement('p');p.textContent=m.desc;const btn=document.createElement('button');btn.className='button light';btn.type='button';btn.dataset.act='use-motion';btn.dataset.id=m.id;card.append(demo,kind,h,p,btn);row.appendChild(card);});paintMotion();}
function paintMotion(){const m=TintaMotion.normalize(state.motion);document.querySelectorAll('.motion-card').forEach(card=>{const def=TintaMotion.get(card.dataset.id),on=m[def.kind]===def.id,btn=card.querySelector('button');btn.setAttribute('aria-pressed',String(on));btn.textContent=on?'✓ En uso · Quitar':'Usar en mi pantalla';btn.setAttribute('aria-label',(on?'Quitar la animación ':'Usar la animación ')+def.name);card.classList.toggle('on',on);});const sum=$('motionSummary');if(sum){const names=Object.values(m).map(id=>TintaMotion.get(id).name);sum.textContent=names.length?'Animaciones: '+names.join(' · '):'';sum.hidden=!names.length;}}
function useMotion(id){const m=TintaMotion.get(id);if(!m)return;const cur=TintaMotion.normalize(state.motion);if(cur[m.kind]===id)delete cur[m.kind];else cur[m.kind]=id;state.motion=cur;state.composed=false;save('Animación «'+m.name+'»');paintMotion();if(state.page==='review')renderReview();toast(cur[m.kind]===id?'«'+m.name+'» aplicada a tu pantalla y a la exportación.':'Animación quitada.');}
/* Paletas: se ven como franjas de color; «Usar» las aplica como capa (fondo, tarjetas y botones). */
function renderPalettes(){const row=$('paletteRow');if(!row||row.dataset.ready)return;row.dataset.ready='1';TintaPalettes.all().forEach(P=>{if(!TintaPalettes.valid(P))return;const card=document.createElement('article');card.className='palette-card';card.dataset.id=P.id;const strip=document.createElement('div');strip.className='palette-strip';strip.setAttribute('aria-hidden','true');[P.bg,P.surface,P.accent,P.accent2,P.ink].forEach(c=>{const i=document.createElement('i');i.style.background=c;strip.appendChild(i);});const h=document.createElement('h3');h.textContent=P.name;const p=document.createElement('p');p.textContent=P.mood;const btn=document.createElement('button');btn.className='button light';btn.type='button';btn.dataset.act='use-palette';btn.dataset.id=P.id;card.append(strip,h,p,btn);if(P.id.startsWith('custom-')){const remove=document.createElement('button');remove.className='button light palette-remove';remove.type='button';remove.dataset.act='remove-palette';remove.dataset.id=P.id;remove.textContent='Eliminar paleta';card.appendChild(remove);}row.appendChild(card);});paintPalettes();}
function paintPalettes(){document.querySelectorAll('.palette-card').forEach(card=>{const on=state.palette===card.dataset.id,P=TintaPalettes.get(card.dataset.id),btn=card.querySelector('button');btn.setAttribute('aria-pressed',String(on));btn.textContent=on?'✓ En uso · Quitar':'Usar en mi pantalla';btn.setAttribute('aria-label',(on?'Quitar la paleta ':'Usar la paleta ')+P.name);card.classList.toggle('on',on);});const sum=$('paletteSummary');if(sum){const P=TintaPalettes.get(state.palette);sum.textContent=P?'Paleta: '+P.name+' (fondo, tarjetas y botones)':'';sum.hidden=!P;}}
function usePalette(id){const P=TintaPalettes.get(id);if(!P)return;state.palette=state.palette===id?null:id;state.composed=false;save('Paleta «'+P.name+'»');paintPalettes();if(state.page==='review')renderReview();else renderPhone();toast(state.palette?'Paleta «'+P.name+'» aplicada. Los estilos que ajustaste a mano se respetan.':'Paleta quitada.');}
/* Mis estilos: editor con vista previa en vivo. Guarda en el almacén de la biblioteca y recarga para reconstruir el catálogo. */
let styleEditingId=null,styleDeleteArmed=false;
const msF=id=>$(id);
function msFillTabs(current){const sel=msF('msTab');sel.replaceChildren();Object.keys(TintaMyStyles.TABS).forEach(t=>{const o=document.createElement('option');o.value=t;o.textContent=t;if(t===current)o.selected=true;sel.appendChild(o);});}
function msFillVariants(tab,current){const sel=msF('msVariant');sel.replaceChildren();const base=document.createElement('option');base.value='';base.textContent='Diseño por defecto de la categoría';sel.appendChild(base);TintaMyStyles.variants(tab,D).forEach(k=>{const o=document.createElement('option');o.value=k;o.textContent=k.split('.')[1];if(k===current)o.selected=true;sel.appendChild(o);});}
function msRead(){return {id:styleEditingId||undefined,name:msF('msName').value,tab:msF('msTab').value,v:msF('msVariant').value,colors:msF('msColors').value,radius:msF('msRadius').value,mode:msF('msMode').value,desc:msF('msDesc').value,tip:msF('msTip').value,code:msF('msCode').value};}
function msPreview(){const r=TintaMyStyles.normalize({...msRead(),name:msF('msName').value||'Vista previa'},D),host=$('stylePreview');if(r.error){$('styleMessage').textContent=r.error;return;}$('styleMessage').textContent='';try{const parts=TintaLibraryTools.preview(r.entry);host.style.background=r.entry.mode==='dark'?'#16181d':'#f5f4ef';const sh=host.shadowRoot||host.attachShadow({mode:'open'});sh.innerHTML='<style>'+BASE+parts.css+'</style>'+parts.html;}catch(e){$('styleMessage').textContent='No se pudo dibujar este código: revisa el HTML y el CSS.';}}
function openStyleDialog(raw,isNew){styleEditingId=raw&&!isNew?raw.id:null;const e=raw||{tab:'Tarjetas',colors:['#ff704b','#ffffff','#242421'],radius:'16',mode:'light'};$('styleTitle').textContent=styleEditingId?'Editar mi estilo':'Crear mi estilo';msF('msName').value=raw?(isNew?(raw.name+' (mío)').slice(0,80):raw.name):'';msFillTabs(TintaMyStyles.TABS[e.tab]?e.tab:'Tarjetas');msFillVariants(msF('msTab').value,e.v||'');msF('msColors').value=(Array.isArray(e.colors)?e.colors:['#ff704b']).join(', ');msF('msRadius').value=String(e.radius||'16');msF('msMode').value=e.mode==='dark'?'dark':'light';msF('msDesc').value=e.desc||'';msF('msTip').value=e.tip||'';msF('msCode').value=e.code||'';$('styleMessage').textContent='';if($('detailDialog').open)$('detailDialog').close();$('styleDialog').showModal();msPreview();msF('msName').focus();}
$('styleForm').addEventListener('input',ev=>{if(ev.target.id==='msTab')msFillVariants(msF('msTab').value,'');msPreview();});
$('styleForm').addEventListener('submit',ev=>{ev.preventDefault();const out=TintaMyStyles.save(msRead(),D);if(out.error){$('styleMessage').textContent=out.error;return;}try{sessionStorage.setItem('estilos-mine-open',out.entry.id);}catch(e){/* sin sessionStorage */}$('styleDialog').close();toast(out.updated?'Estilo actualizado.':'Estilo guardado en «Mis estilos».');setTimeout(()=>{location.hash='#bloques';location.reload();},350);});
function mineBlock(){return detailId&&BY_ID[detailId]&&BY_ID[detailId].raw?BY_ID[detailId]:null;}
function updateMineButtons(){const b=detailId&&BY_ID[detailId];$('detailMine').hidden=!(b&&b.raw);$('editStyle').hidden=!(b&&b.mine);$('deleteStyle').hidden=!(b&&b.mine);styleDeleteArmed=false;$('deleteStyle').textContent='Eliminar mi estilo';}
function deleteMyStyle(){const b=mineBlock();if(!b||!b.mine)return;if(!styleDeleteArmed){styleDeleteArmed=true;$('deleteStyle').textContent='¿Seguro? Pulsa otra vez para eliminar';return;}const out=TintaMyStyles.remove(b.raw.id);if(out.error){toast(out.error);return;}try{sessionStorage.setItem('estilos-mine-open','deleted');}catch(e){}toast('Estilo eliminado.');setTimeout(()=>{location.hash='#bloques';location.reload();},350);}
/* ───── Todas las pantallas de la app ───── */
let screenView='inicio',navMap=[];
function multiOn(){return !!state.multi&&!!resolved('nav')&&!!TintaSectors.detect(state.brief);}
function navDescriptors(block){const t=document.createElement('template');t.innerHTML=editedBlock(block).html;return [...t.content.querySelectorAll('button,a')].map(b=>({text:b.textContent,aria:b.getAttribute('aria-label'),cls:b.className}));}
function screenPlan(){const cardId=idsFor('cards')[0]||'c-coral',headerId=resolved('header')||idsFor('header')[0]||'h-minimal';return TintaScreens.plan({headerId:BY_ID[headerId]?headerId:null,plainHeaderId:BY_ID['h-minimal']?'h-minimal':null,cardId:BY_ID[cardId]?cardId:null,actionId:idsFor('actions')[0]||null,hasList:!!BY_ID['lib-lis-1'],hasAvatar:!!BY_ID['lib-ava-3']});}
function screensAvail(){const nid=resolved('nav');if(!nid)return ['inicio'];navMap=TintaScreens.mapNav(navDescriptors(BY_ID[nid]));const plan=screenPlan();return ['inicio',...new Set(navMap.filter(v=>v&&v!=='inicio'&&plan[v]&&plan[v].length))];}
