function agentApplyPlan(plan){
 const validation=TintaAgentCore.validatePlan(plan.operations,{hasPalette:id=>!!TintaPalettes.get(id),hasBlock:id=>!!BY_ID[id],roleOf:id=>BY_ID[id]?.role,fieldCount:id=>contentModel(BY_ID[id]).fields.length});
 if(!validation.ok)return {ok:false,message:'El plan no superó la validación: '+validation.errors.join(' ')};
 const backup={selected:[...state.selected],choices:{...state.choices},content:JSON.parse(JSON.stringify(state.content||{})),palette:state.palette,composed:state.composed};
 const changed=[];
 try{
  for(const op of plan.operations){
   if(op.type==='set_palette'){state.palette=op.paletteId;changed.push(op.paletteId?'Paleta '+TintaPalettes.get(op.paletteId).name+' aplicada.':'Paleta quitada.');}
   else if(op.type==='remove_component'){const ids=idsFor(op.role);state.selected=state.selected.filter(id=>BY_ID[id].role!==op.role);state.choices[op.role]=null;changed.push(ids.length?'Quité '+ROLES[op.role].toLowerCase()+'.':'No había '+ROLES[op.role].toLowerCase()+' en la pantalla.');}
   else if(op.type==='add_component'){const block=BY_ID[op.blockId];if(!state.selected.includes(block.id)){state.selected.push(block.id);trackRecent(block.id);changed.push('Añadí «'+block.name+'».');}else changed.push('«'+block.name+'» ya estaba en tu diseño.');}
   else if(op.type==='replace_component'){const block=BY_ID[op.blockId];state.selected=state.selected.filter(id=>BY_ID[id].role!==op.role);state.selected.push(block.id);state.choices[op.role]=block.id;changed.push('Sustituí '+ROLES[op.role].toLowerCase()+' por «'+block.name+'».');}
   else if(op.type==='update_text'){const block=BY_ID[op.blockId],fields=contentModel(block).fields,values=Array.isArray(state.content[block.id])?[...state.content[block.id]]:fields.map(f=>f.value);while(values.length<fields.length)values.push(fields[values.length].value);values[op.fieldIndex]=op.value;state.content[block.id]=values;changed.push('Actualicé el texto a «'+op.value+'».');}
  }
  state.composed=!!state.selected.length&&!conflicts().length;
 }catch(error){state.selected=backup.selected;state.choices=backup.choices;state.content=backup.content;state.palette=backup.palette;state.composed=backup.composed;return {ok:false,message:'Se cancelaron todos los cambios porque ocurrió un error al aplicarlos.'};}
 return {ok:true,message:changed.join(' ')+' Plan local validado: '+plan.operations.length+' operación'+(plan.operations.length===1?'':'es')+'.',plan};
}
function agentApplyInstruction(raw){
 const plan=agentBuildPlan(raw);
 if(!plan.operations.length)return {ok:false,message:'Todavía no identifiqué un cambio concreto. Prueba con: «usa colores azules», «añade un botón», «quita las tarjetas» o «quita la barra inferior». No he modificado tu diseño.'};
 const result=agentApplyPlan(plan);if(!result.ok)return result;
 save('Agente: '+String(raw||'').slice(0,60),'agent-command');paintPalettes();renderReview();renderPhone();
 return {ok:true,message:result.message,plan};
}
let agentRequestBusy=false;
function agentStateSignature(){return JSON.stringify({brief:state.brief||'',selected:state.selected,choices:state.choices,content:state.content,palette:state.palette,composed:state.composed});}
function agentTaskKind(text){const t=agentNormalize(String(text||''));if(/codigo|javascript|typescript|react|html|css|bug|error|funcion|api/.test(t))return'code';if(/disena|diseno|estilo|visual|interfaz|pantalla|componente|layout|tarjeta|color/.test(t))return'design';if(/explica|analiza|compara|razona|arquitectura|planifica/.test(t))return'reasoning';return'general';}
function agentParseModelPlan(answer){let payload=String(answer||'').replace(/^\s*\x60{3}(?:json)?\s*/i,'').replace(/\s*\x60{3}\s*$/,'').trim();const first=payload.indexOf('{'),last=payload.lastIndexOf('}');if(first<0||last<=first)throw Error('La respuesta no contiene un JSON reconocible.');const plan=JSON.parse(payload.slice(first,last+1));if(!plan||typeof plan!=='object'||Array.isArray(plan)||Object.keys(plan).some(k=>!['operations','summary'].includes(k))||!Array.isArray(plan.operations)||plan.operations.length>12)throw Error('El formato JSON del plan no es válido o supera las 12 operaciones.');if(plan.summary!==undefined&&(!Array.isArray(plan.summary)||plan.summary.length>12||plan.summary.some(item=>typeof item!=='string'||item.length>180)))throw Error('El resumen del plan contiene datos no válidos.');if(plan.operations.length){const validation=TintaAgentCore.validatePlan(plan.operations,{hasPalette:id=>!!TintaPalettes.get(id),hasBlock:id=>!!BY_ID[id],roleOf:id=>BY_ID[id]?.role,fieldCount:id=>contentModel(BY_ID[id]).fields.length});if(!validation.ok)throw Error(validation.errors.join(' '));}return plan;}
function agentAutoCandidates(instruction){const kind=agentTaskKind(instruction),profiles=TintaProviderManager.list(),ranked=[];profiles.forEach((p,pi)=>(p.workingModels||[]).forEach((model,mi)=>{const n=String(model).toLowerCase();let score=0;if(kind==='code'&&/(coder|code|dev|program)/.test(n))score+=5;if(kind==='reasoning'&&/(reason|think|r1|o1|o3|opus)/.test(n))score+=5;if(kind==='design'&&/(vision|creative|pro|sonnet|gemini)/.test(n))score+=3;if(/mini|flash|fast|lite/.test(n))score+=1;ranked.push({providerId:p.id,model,score,order:pi*100+mi});}));return ranked.sort((a,b)=>b.score-a.score||a.order-b.order).slice(0,4).map(({providerId,model})=>({providerId,model}));}
