    const posY=document.createElement('input');posY.type='range';posY.min='0';posY.max='100';posY.value=value?.positionY??50;posY.dataset.mediaPositionY=i;label('Posición vertical · '+posY.value+'%',section).appendChild(posY);posY.addEventListener('input',()=>posY.parentElement.firstChild.textContent='Posición vertical · '+posY.value+'%');
