document.addEventListener('click',ev=>{const b=ev.target.closest('[data-act]');if(!b||b.disabled)return;const act=b.dataset.act;if(act==='edit-media')openMedia(b.dataset.id);if(act==='close-media')$('mediaDialog').close();if(act==='reset-media-image'){mediaDraft=readMediaForm();mediaDraft.images[+b.dataset.index]=null;renderMediaFields();$('mediaMessage').textContent='Imagen original preparada. Pulsa Aplicar para conservar el cambio.';}if(act==='reset-media'){delete state.assets[mediaId];state.composed=false;save();renderReview();$('mediaDialog').close();toast('Imágenes y destinos originales restaurados.');}});

