function editedBlock(block,forced){const values=forced||state.content[block.id];if(!values)return TintaAssets.apply(block,state.assets[block.id]);const model=contentModel(block);model.fields.forEach((f,i)=>{if(typeof values[i]==='string')f.set(values[i]);});return TintaAssets.apply({...block,html:model.root.innerHTML},state.assets[block.id]);}
function normalizedDraft(raw){if(!raw||typeof raw!=='object'||!Array.isArray(raw.selected))throw Error('El archivo no contiene una selección de Tinta válida.');const selected=[...new Set(raw.selected.filter(id=>typeof id==='string'))];if(selected.length>CATALOG.length||selected.some(id=>!Object.hasOwn(BY_ID,id)))throw Error('Este proyecto usa bloques que no están en tu biblioteca actual. Recupera esos diseños antes de abrirlo.');const layout={};if(raw.layout&&typeof raw.layout==='object')Object.entries(raw.layout).forEach(([id,v])=>{if(!selected.includes(id)||!v||typeof v!=='object')return;const n=(x,min,max,step=1)=>{const value=Number(x);return Number.isFinite(value)?Math.min(max,Math.max(min,Math.round(value/step)*step)):null;};const item={width:n(v.width,60,100,5)??100,gap:n(v.gap,0,32)??0,opacity:n(v.opacity,40,100,5)??100,radius:n(v.radius,0,36)??0,align:['left','center','right'].includes(v.align)?v.align:'center'};if(Object.values(item).some(x=>x!==null&&x!==undefined))layout[id]=item;});const layerOrder=Array.isArray(raw.layerOrder)?[...new Set(raw.layerOrder.filter(id=>selected.includes(id)))]:[];selected.forEach(id=>{if(!layerOrder.includes(id))layerOrder.push(id);});const choices={header:null,nav:null};['header','nav'].forEach(role=>{const id=raw.choices&&raw.choices[role];if(selected.includes(id)&&BY_ID[id].role===role)choices[role]=id;});const content={};if(raw.content&&typeof raw.content==='object')Object.keys(raw.content).forEach(id=>{if(Object.hasOwn(BY_ID,id)&&Array.isArray(raw.content[id]))content[id]=raw.content[id].slice(0,200).map(v=>typeof v==='string'?v.slice(0,500):null);});const repeat={};if(raw.repeat&&typeof raw.repeat==='object')Object.keys(raw.repeat).forEach(id=>{const n=Number(raw.repeat[id]);if(selected.includes(id)&&BY_ID[id].role==='cards'&&Number.isInteger(n)&&n>1&&n<=MAX_REPEAT)repeat[id]=n;});const typeStyles={};if(raw.typeStyles&&typeof raw.typeStyles==='object')Object.entries(raw.typeStyles).forEach(([id,v])=>{if(!selected.includes(id)||!v||typeof v!=='object')return;const font=['original','Arial,Helvetica,sans-serif','Georgia,serif','system-ui,sans-serif','Verdana,sans-serif','Trebuchet MS,sans-serif'].includes(v.fontFamily)?v.fontFamily:'original';const scale=Number(v.scale);typeStyles[id]={fontFamily:font,scale:Number.isFinite(scale)?Math.min(125,Math.max(85,Math.round(scale/5)*5)):100};});const innerStyles={};if(raw.innerStyles&&typeof raw.innerStyles==='object')Object.entries(raw.innerStyles).forEach(([id,list])=>{if(!selected.includes(id)||!Array.isArray(list))return;innerStyles[id]=list.slice(0,100).filter(x=>x&&typeof x.selector==='string'&&x.selector.length<500).map(x=>({selector:x.selector,text:typeof x.text==='string'?x.text.slice(0,500):null,style:{color:/^#[0-9a-f]{6}$/i.test(x.style?.color||'')?x.style.color:'',backgroundColor:/^#[0-9a-f]{6}$/i.test(x.style?.backgroundColor||'')?x.style.backgroundColor:'',borderColor:/^#[0-9a-f]{6}$/i.test(x.style?.borderColor||'')?x.style.borderColor:'',borderWidth:Math.min(6,Math.max(0,Number(x.style?.borderWidth)||0))+'px',borderRadius:Math.min(32,Math.max(0,Number(x.style?.borderRadius)||0))+'px'}}));});const innerHtml={};if(raw.innerHtml&&typeof raw.innerHtml==='object')Object.entries(raw.innerHtml).forEach(([id,markup])=>{if(!selected.includes(id)||typeof markup!=='string'||markup.length>120000)return;const tpl=document.createElement('template');tpl.innerHTML=markup;tpl.content.querySelectorAll('script,iframe,object,embed,link,meta,base').forEach(el=>el.remove());tpl.content.querySelectorAll('*').forEach(el=>{[...el.attributes].forEach(a=>{if(/^on/i.test(a.name)||a.name==='srcdoc'||(['href','src','xlink:href','action','formaction','poster','cite','background'].includes(a.name)&&/^\s*(javascript:|data:text\/html)/i.test(a.value)))el.removeAttribute(a.name);});});innerHtml[id]=tpl.innerHTML;});return {brief:typeof raw.brief==='string'?raw.brief.slice(0,240):'',selected,choices,content,repeat,motion:TintaMotion.normalize(raw.motion),palette:TintaPalettes.normalize(raw.palette),multi:raw.multi===true,assets:TintaAssets.normalize(raw.assets,BY_ID),ui:TintaStates.normalize(raw.ui,BY_ID),buttonStyles:TintaButtonStyle.normalize(raw.buttonStyles,BY_ID),cardStyles:TintaCardStyle.normalize(raw.cardStyles,BY_ID),typeStyles,innerStyles,innerHtml,layout,layerOrder};}
function draftSnapshot(){return JSON.parse(JSON.stringify({brief:state.brief,selected:state.selected,choices:state.choices,content:state.content,repeat:state.repeat,motion:state.motion,palette:state.palette,multi:state.multi,assets:state.assets,ui:state.ui,buttonStyles:state.buttonStyles,cardStyles:state.cardStyles,typeStyles:state.typeStyles,innerStyles:state.innerStyles,innerHtml:state.innerHtml,layout:state.layout,layerOrder:state.layerOrder}));}
let editingId=null;
function adaptTexts(){const sector=TintaSectors.detect(state.brief);if(!sector){toast('No reconocí el sector. Prueba con: tienda, café, finanzas, gimnasio, viajes, salud, música o curso.');return;}let changed=0,kept=0,offset=0;state.selected.forEach(id=>{const block=BY_ID[id];if(!block||block.role==='nav')return;if(state.content[id]){kept++;return;}const fields=contentModel(block).fields;const out=TintaSectors.fill(sector.id,fields,{offset,role:block.role==='header'?'header':undefined});offset+=2;if(!out||!out.some(v=>v))return;state.content[id]=out.map((v,i)=>(v||fields[i].value).slice(0,500));changed++;});if(!changed){toast(kept?'Tus textos editados a mano se respetan; no hay nada que adaptar.':'No hay bloques con textos que adaptar.');return;}state.composed=false;save('Adaptar textos al sector','adapt-text');renderReview();toast('Textos adaptados a «'+sector.name+'» en '+changed+(changed===1?' bloque':' bloques')+(kept?' · '+kept+' editados a mano se respetan':'')+'. Puedes deshacer.');}
/* Compartir por enlace: copia un enlace con la pantalla; al abrirlo, se guarda como copia en Mis proyectos. */
async function shareLink(){if(!state.selected.length){toast('Elige al menos un bloque antes de compartir.');return;}try{const {code}=await TintaShare.encode(draftSnapshot());const url=location.origin+location.pathname+'#'+code,box=$('shareBox'),input=$('shareLink');input.value=url;box.hidden=false;$('shareNote').textContent=url.length>TintaShare.LONG_LINK?'Enlace largo ('+url.length+' caracteres): algunas apps lo recortan. Si no abre, usa «Guardar pantalla» y descarga el JSON. ':'';$('shareNote').textContent+='No incluye imágenes subidas.';input.focus();input.select();let copied=false;try{await navigator.clipboard.writeText(url);copied=true;}catch(e){/* el cuadro queda seleccionado para copiar a mano */}toast(copied?'Enlace copiado. Quien lo abra lo recibe como copia en Mis proyectos.':'Copia el enlace seleccionado (Ctrl+C).');}catch(e){toast('No se pudo crear el enlace en este navegador.');}}
async function importShared(){const hash=location.hash;if(!TintaShare.isShareHash(hash))return;const clean=()=>history.replaceState(null,'',location.pathname+location.search);try{const raw=await TintaShare.decode(hash),draft=normalizedDraft(raw);clean();openProjects();addProject('Compartido · '+(draft.brief||'Mi pantalla').slice(0,60),draft);}catch(e){clean();renderPage('home',false);toast('El enlace no es válido o usa bloques que no tienes en tu biblioteca.');}}
function openText(id){if(!state.selected.includes(id))return;editingId=id;const model=contentModel(editedBlock(BY_ID[id]));$('textTitle').textContent=BY_ID[id].name;$('textFields').replaceChildren();model.fields.forEach((field,i)=>{const label=document.createElement('label');label.textContent=field.label+' '+(i+1);const input=document.createElement('textarea');input.value=field.value;input.maxLength=500;input.rows=2;input.dataset.field=i;label.appendChild(input);$('textFields').appendChild(label);});if(!model.fields.length)$('textFields').textContent='Este bloque no tiene textos editables.';$('textDialog').showModal();}
$('textForm').addEventListener('submit',ev=>{ev.preventDefault();state.content[editingId]=[...$('textFields').querySelectorAll('textarea')].map(t=>t.value.slice(0,500));state.composed=false;save();renderReview();$('textDialog').close();toast('Textos actualizados. El diseño se conserva.');});
const TINTA_PROJECT_KEY='estilos-tinta-projects-v1';let pendingProject=null;
function projectMessage(message){$('projectMessage').textContent=message;}
function readTintaProjects(){try{const raw=JSON.parse(localStorage.getItem(TINTA_PROJECT_KEY)||'[]');if(!Array.isArray(raw)||raw.length>30||raw.some(p=>!p||typeof p.id!=='string'||typeof p.name!=='string'||!p.draft))throw Error();return raw;}catch(e){projectMessage('No se pueden leer los proyectos guardados. No se reemplazará su almacenamiento. Puedes descargar tu pantalla como JSON.');return null;}}
function writeTintaProjects(list){try{localStorage.setItem(TINTA_PROJECT_KEY,JSON.stringify(list));return true;}catch(e){projectMessage('No se pudo guardar: almacenamiento lleno o bloqueado. Descarga el proyecto como JSON para conservarlo.');return false;}}
function projectId(){return 't-'+(globalThis.crypto&&crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+'-'+Math.random().toString(36).slice(2));}
function addProject(name,draft){const list=readTintaProjects();if(!list)return;if(!name.trim()){projectMessage('Pon un nombre a tu pantalla.');$('tintaProjectName').focus();return;}if(!draft.selected.length){projectMessage('Elige al menos un bloque antes de guardar.');return;}if(list.length>=30){projectMessage('Ya tienes 30 proyectos. Descarga o elimina una copia antes de añadir otra.');return;}if(writeTintaProjects([{id:projectId(),name:name.trim().slice(0,80),updated:new Date().toISOString(),draft},...list])){pendingProject=null;renderTintaProjects();projectMessage('Copia guardada: '+name.trim().slice(0,80));}}
function openProjects(){pendingProject=null;projectMessage('');$('tintaProjectName').value=state.brief?state.brief.slice(0,80):'';renderTintaProjects();renderLegacyProjects();$('projectsDialog').showModal();}
function renderLegacyProjects(){const host=$('legacyProjectList');host.replaceChildren();try{const list=JSON.parse(localStorage.getItem('estilos-studio-projects-v1')||'[]');if(!Array.isArray(list))throw Error();list.filter(p=>p&&typeof p.id==='string'&&/^[a-zA-Z0-9-]+$/.test(p.id)&&typeof p.name==='string'&&p.state).slice(0,30).forEach(p=>{const row=document.createElement('div');row.className='legacy-row';const name=document.createElement('span');name.textContent=p.name.slice(0,80);const a=document.createElement('a');a.href='agente.html?projects=1&project='+encodeURIComponent(p.id);a.textContent='Abrir en su editor ↗';row.append(name,a);host.appendChild(row);});if(!host.children.length)host.textContent='No hay proyectos clásicos guardados en este navegador.';}catch(e){host.textContent='Los proyectos clásicos no están accesibles en esta vista. Abre la app en el navegador donde los guardaste.';}}
function renderTintaProjects(){const list=readTintaProjects(),host=$('tintaProjectList');host.replaceChildren();if(!list)return;if(!list.length){const p=document.createElement('p');p.className='dialog-note';p.textContent='Todavía no has guardado proyectos de Tinta.';host.appendChild(p);}list.forEach(p=>{const row=document.createElement('article');row.className='tinta-project';row.dataset.projectId=p.id;const name=document.createElement('input');name.value=p.name.slice(0,80);name.maxLength=80;name.setAttribute('aria-label','Nombre de '+p.name);const meta=document.createElement('small');const date=new Date(p.updated);meta.textContent=(Array.isArray(p.draft.selected)?p.draft.selected.length:0)+' bloques · '+(Number.isNaN(+date)?'Sin fecha':date.toLocaleString('es'));const acts=document.createElement('div');acts.className='project-buttons';[['project-open','Abrir'],['project-rename','Renombrar'],['project-update','Actualizar'],['project-json','JSON'],['project-delete','Eliminar']].forEach(([act,text])=>{const button=document.createElement('button');button.dataset.act=act;button.dataset.projectId=p.id;button.textContent=text;acts.appendChild(button);});row.append(name,meta,acts);if(pendingProject&&pendingProject.id===p.id){const box=document.createElement('div');box.className='project-confirm-tinta';const text=document.createElement('p');text.textContent=pendingProject.act==='project-open'?'Abrir reemplazará tu pantalla de trabajo. Guarda una copia o descarga su JSON si quieres conservarla.':pendingProject.act==='project-update'?'Actualizar sustituirá esta copia por tu pantalla de trabajo actual.':'¿Eliminar esta copia guardada? Tu pantalla de trabajo no se borrará.';box.appendChild(text);[['project-confirm','Sí, continuar'],['project-cancel','Cancelar']].forEach(([act,label])=>{const button=document.createElement('button');button.dataset.act=act;button.dataset.projectId=p.id;button.textContent=label;box.appendChild(button);});row.appendChild(box);}host.appendChild(row);});}
function downloadProject(name,draft){if(!draft.selected.length){projectMessage('Primero elige algún bloque.');return;}const blob=new Blob([JSON.stringify({format:'estilos-tinta-project',version:1,name:name.trim().slice(0,80)||'Mi pantalla',draft},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='proyecto-tinta.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),4000);}
$('saveProjectForm').addEventListener('submit',ev=>{ev.preventDefault();addProject($('tintaProjectName').value,draftSnapshot());});
$('tintaImport').addEventListener('change',async ev=>{const file=ev.target.files[0];if(!file)return;try{if(file.size>8*1024*1024)throw Error('El archivo supera el límite de 8 MB.');const data=JSON.parse(await file.text());if(data.format!=='estilos-tinta-project'||data.version!==1||typeof data.name!=='string')throw Error('Formato no válido. Importa un proyecto JSON de Tinta (versión 1).');const draft=normalizedDraft(data.draft);addProject(data.name,draft);}catch(e){projectMessage(e.message||'No se pudo importar.');}finally{ev.target.value='';}});
function projectAction(act,id){const list=readTintaProjects();if(!list)return;const project=list.find(p=>p.id===id);if(!project){projectMessage('El proyecto ya no está disponible.');return;}if(act==='project-json'){downloadProject(project.name,project.draft);return;}if(act==='project-rename'){const row=[...$('tintaProjectList').children].find(el=>el.dataset.projectId===id);const name=row.querySelector('input').value.trim().slice(0,80);if(!name){projectMessage('El nombre no puede estar vacío.');return;}if(writeTintaProjects(list.map(p=>p.id===id?{...p,name}:p))){renderTintaProjects();projectMessage('Nombre actualizado.');}return;}if(act==='project-cancel'){pendingProject=null;renderTintaProjects();return;}if(['project-open','project-update','project-delete'].includes(act)){pendingProject={id,act};renderTintaProjects();return;}if(act!=='project-confirm'||!pendingProject||pendingProject.id!==id)return;const action=pendingProject.act;if(action==='project-open'){try{const draft=normalizedDraft(project.draft);Object.assign(state,draft);state.composed=false;$('idea').value=state.brief;resetDraftHistory();save();pendingProject=null;$('projectsDialog').close();go('review');toast('Proyecto abierto: '+project.name);}catch(e){projectMessage(e.message);}return;}if(action==='project-update'&&!state.selected.length){projectMessage('La pantalla está vacía. No se actualizó la copia.');return;}const next=action==='project-delete'?list.filter(p=>p.id!==id):list.map(p=>p.id===id?{...p,draft:draftSnapshot(),updated:new Date().toISOString()}:p);if(writeTintaProjects(next)){pendingProject=null;renderTintaProjects();projectMessage(action==='project-delete'?'Copia eliminada.':'Copia actualizada.');}}

/* Constructor de paletas HSL: la persona ajusta el color principal y Tinta deriva los roles. */
(function setupHslPaletteBuilder(){
 const hue=$('customPaletteHue'),sat=$('customPaletteSat'),light=$('customPaletteLight'),picker=$('customPaletteColor');
 if(!hue||!sat||!light||!picker)return;
 function syncFromHsl(){const hex=TintaPalettes.hslToHex(hue.value,sat.value,light.value);picker.value=hex;paint();}
 function paint(){const h=Number(hue.value),s=Number(sat.value),l=Number(light.value),P={bg:TintaPalettes.hslToHex(h,Math.min(s,18),97),surface:'#ffffff',accent:TintaPalettes.hslToHex(h,s,l),accent2:TintaPalettes.hslToHex(h,Math.min(72,s),Math.min(88,l+24)),ink:TintaPalettes.hslToHex(h,Math.min(28,s),13),line:TintaPalettes.hslToHex(h,Math.min(24,s),88)};
  $('hueValue').textContent=h+'°';$('satValue').textContent=s+'%';$('lightValue').textContent=l+'%';
  const live=$('paletteLive');[P.bg,P.surface,P.accent,P.accent2,P.ink].forEach((v,i)=>live.children[i].style.background=v);
  const ratio=TintaPalettes.contrast(P.accent,TintaPalettes.onAccent(P.accent));$('paletteContrast').textContent='Contraste del texto sobre el color principal: '+ratio.toFixed(2)+':1 · '+(ratio>=4.5?'Cumple WCAG AA para texto normal.':'No alcanza 4.5:1 para texto normal; Tinta ajustará el color del texto al aplicar.');
 }
 [hue,sat,light].forEach(el=>el.addEventListener('input',syncFromHsl));
 picker.addEventListener('input',()=>{const v=TintaPalettes.hexToHsl(picker.value);if(!v)return;hue.value=v.h;sat.value=v.s;light.value=Math.min(90,Math.max(5,v.l));paint();});
 $('saveCustomPalette').addEventListener('click',()=>{const P=TintaPalettes.createFromHsl({name:$('customPaletteName').value,h:hue.value,s:sat.value,l:light.value});if(!P){toast('No se pudo crear la paleta.');return;}const row=$('paletteRow');row.dataset.ready='';row.replaceChildren();renderPalettes();usePalette(P.id);});
 paint();
})();
document.addEventListener('click',ev=>{const button=ev.target.closest('[data-act]');if(!button)return;const act=button.dataset.act;if(act==='edit-text')openText(button.dataset.id);if(act==='adapt-text')adaptTexts();if(act==='use-template')useTemplate(button.dataset.id);if(act==='use-motion')useMotion(button.dataset.id);if(act==='use-palette')usePalette(button.dataset.id);if(act==='remove-palette'){const id=button.dataset.id,P=TintaPalettes.get(id);if(P&&TintaPalettes.removeCustom(id)){if(state.palette===id){state.palette=null;save('Quitar paleta personalizada');if(state.page==='review')renderReview();else renderPhone();}const card=button.closest('.palette-card');if(card)card.remove();paintPalettes();toast('Paleta personalizada eliminada.');}}if(act==='view-screen')setScreenView(button.dataset.id);if(act==='new-mystyle')openStyleDialog(null,true);if(act==='close-mystyle')$('styleDialog').close();if(act==='clone-mystyle'){const b=mineBlock();if(b)openStyleDialog(b.raw,true);}if(act==='edit-mystyle'){const b=mineBlock();if(b&&b.mine)openStyleDialog(b.raw,false);}if(act==='delete-mystyle')deleteMyStyle();if(act==='share-link')shareLink();if(act==='close-text')$('textDialog').close();if(act==='reset-text'){delete state.content[editingId];state.composed=false;save();renderReview();$('textDialog').close();toast('Textos originales restaurados.');}if(act==='projects'||act==='save-dialog')openProjects();if(act==='close-projects')$('projectsDialog').close();if(act==='backup-draft')downloadProject($('tintaProjectName').value,draftSnapshot());if(act.startsWith('project-'))projectAction(act,button.dataset.projectId);});

document.addEventListener('click',ev=>{const b=ev.target.closest('[data-act]');if(!b||b.disabled)return;const action=b.dataset.act,id=b.dataset.id;if(action==='go')go(b.dataset.page);if(action==='filter'){state.filter=b.dataset.filter;renderGallery();}if(action==='chosen'){state.chosenOnly=!state.chosenOnly;renderGallery();}if(action==='fav')toggleFav(id);if(action==='favs-only'){state.favsOnly=!state.favsOnly;renderGallery();}if(action==='recent-only'){state.recentOnly=!state.recentOnly;renderGallery();}if(action==='select')toggle(id);if(action==='detail')openDetail(id);if(action==='close-detail')$('detailDialog').close();if(action==='select-detail')toggle(detailId);if(action==='clear'){state.selected=[];state.choices={header:null,nav:null};state.composed=false;save();renderGallery();toast('Selección vacía. Tu idea sigue guardada.');}if(action==='compose'){if(conflicts().length||!state.selected.length)return;state.composed=true;renderReview();save();toast('Tu pantalla está compuesta. No cambié tus bloques.');if(innerWidth<721)document.querySelector('.composition-area').scrollIntoView({behavior:'smooth',block:'start'});}if(action==='export')download();if(action==='idea'){const ideas={tienda:'Una tienda de ropa con tarjetas de producto y una barra inferior.',comida:'Una app para mi cafetería, con tarjetas grandes y una navegación sencilla.',finanzas:'Una app de finanzas personales con un balance claro y tarjetas con relieve.',libre:''};state.brief=ideas[b.dataset.idea]||'';$('idea').value=state.brief;save();$('idea').focus();}if(action==='hello'){const avatar=document.querySelector('.avatar-button');avatar.classList.remove('hello');void avatar.offsetWidth;avatar.classList.add('hello');$('greeting').innerHTML='Vamos a crear algo <b>muy tuyo.</b>';setTimeout(()=>avatar.classList.remove('hello'),800);}if(action==='menu'){const open=$('siteMenu').hidden;$('siteMenu').hidden=!open;b.setAttribute('aria-expanded',open);}if(action==='reset'){state.content={};state.assets={};state.repeat={};state.motion={};state.palette=null;state.multi=false;state.ui={};state.buttonStyles={};state.cardStyles={};state.selected=[];state.choices={header:null,nav:null};state.brief='';state.composed=false;$('idea').value='';save();go('home');toast('Un lienzo nuevo. Tus proyectos del editor clásico no se modificaron.');}if(action==='move'){const ids=idsFor(BY_ID[id].role),from=ids.indexOf(id),to=from+Number(b.dataset.dir);if(from<0||to<0||to>=ids.length)return;const a=state.selected.indexOf(id),z=state.selected.indexOf(ids[to]);[state.selected[a],state.selected[z]]=[state.selected[z],state.selected[a]];state.composed=false;save();renderReview();}});
document.addEventListener('change',ev=>{const input=ev.target.closest('[data-choice]');if(!input)return;const id=input.value,role=input.dataset.choice;if(state.selected.includes(id)&&BY_ID[id].role===role){state.choices[role]=id;state.composed=false;save();renderReview();}});
$('agentChatForm')?.addEventListener('submit',ev=>{ev.preventDefault();submitAgentInstruction();});

/* Centro de conexiones: credenciales cifradas y peticiones a través del gateway privado. */
const aiDialog=$('aiConnectionsDialog'),aiWorking=new Map(),aiFailed=new Map();let aiCurrentProfileId=null;
function aiStatus(message,kind='info'){const el=$('aiConnectionStatus');if(el){el.textContent=message;el.dataset.kind=kind;}}
function aiBackendStatus(message,kind='info'){const el=$('aiBackendStatus');if(el){el.textContent=message;el.dataset.kind=kind;}}
function aiNumber(value){return new Intl.NumberFormat('es-ES').format(Math.max(0,Number(value)||0));}
function aiUsageNode(tag,className,text){const node=document.createElement(tag);if(className)node.className=className;if(text!==undefined)node.textContent=String(text);return node;}
function aiRenderUsage(data){const totals=$('aiUsageTotals'),providers=$('aiUsageProviders'),note=$('aiUsageNote');totals.replaceChildren();providers.replaceChildren();const t=data.totals||{};[['Solicitudes',t.requests],['Tokens informados',t.totalTokens],['Errores',t.errors]].forEach(([label,value])=>{const card=aiUsageNode('div','ai-usage-metric');card.append(aiUsageNode('span','',label),aiUsageNode('strong','',aiNumber(value)));totals.appendChild(card);});(data.providers||[]).forEach(provider=>{const card=aiUsageNode('article','ai-usage-provider'),head=aiUsageNode('div','ai-usage-provider-head');head.append(aiUsageNode('strong','',provider.name),aiUsageNode('small','',aiNumber(provider.requestsToday)+' / '+aiNumber(provider.requestsPerDay)+' hoy'));card.appendChild(head);card.appendChild(aiUsageNode('div','ai-usage-provider-minute','Último minuto: '+aiNumber(provider.requestsThisMinute)+' / '+aiNumber(provider.requestsPerMinute)));const bar=aiUsageNode('div','ai-usage-progress');bar.setAttribute('role','progressbar');bar.setAttribute('aria-valuemin','0');bar.setAttribute('aria-valuemax',String(provider.requestsPerDay));bar.setAttribute('aria-valuenow',String(provider.requestsToday));const fill=aiUsageNode('span','');fill.style.width=Math.min(100,provider.requestsToday/Math.max(1,provider.requestsPerDay)*100)+'%';bar.appendChild(fill);card.appendChild(bar);card.appendChild(aiUsageNode('small','ai-usage-provider-summary',aiNumber(provider.requests)+' llamadas · '+aiNumber(provider.totalTokens)+' tokens informados · '+aiNumber(provider.errors)+' errores (7 días)'));if(provider.models?.length){const details=aiUsageNode('details','ai-usage-model-details');details.appendChild(aiUsageNode('summary','','Desglose por modelo'));provider.models.forEach(model=>{const row=aiUsageNode('div','ai-usage-model-row');row.append(aiUsageNode('span','',model.model==='__catalog__'?'Catálogo de modelos':model.model),aiUsageNode('small','',aiNumber(model.requests)+' llamadas · '+aiNumber(model.promptTokens+model.completionTokens)+' tokens · '+aiNumber(model.errors)+' errores'));details.appendChild(row);});card.appendChild(details);}providers.appendChild(card);});if(note)note.textContent='Periodo: '+data.from+' a '+data.to+' (UTC). Los tokens solo aparecen cuando el proveedor incluye usage en su respuesta.';}
async function aiRefreshUsage(){const host=$('aiUsageTotals'),providers=$('aiUsageProviders'),button=$('aiUsageRefresh'),note=$('aiUsageNote');if(!host||!providers)return;if(!TintaProviderManager.isAuthenticated()){host.replaceChildren(aiUsageNode('p','ai-empty','Conecta el servidor privado para ver el consumo.'));providers.replaceChildren();if(note)note.textContent='';return;}if(button)button.disabled=true;if(note)note.textContent='Actualizando métricas…';try{aiRenderUsage(await TintaProviderManager.getUsage(7));}catch(error){host.replaceChildren(aiUsageNode('p','ai-usage-error','No se pudieron cargar las métricas: '+error.message));providers.replaceChildren();if(note)note.textContent='Actualiza D1 con la migración 0002_usage_limits.sql y despliega el Worker nuevo.';}finally{if(button)button.disabled=false;}}
function aiProfileId(){return 'provider-'+(crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+'-'+Math.random().toString(36).slice(2));}
function aiLoadSessionResults(id){aiWorking.clear();aiFailed.clear();const p=TintaProviderManager.get(id);(p?.workingModels||[]).forEach(m=>aiWorking.set(m,''));}
function aiRefreshAgentModels(){const s=$('agentAIModel');if(!s)return;const chosen=s.value;s.replaceChildren();const local=document.createElement('option');local.value='';local.textContent='Modo local · reglas integradas';s.appendChild(local);if(TintaProviderManager.isAuthenticated()&&aiCurrentProfileId){const profiles=TintaProviderManager.list();const candidates=profiles.flatMap(p=>(p.workingModels||[]).map(m=>({providerId:p.id,model:m})));if(candidates.length){const auto=document.createElement('option');auto.value='__auto__';auto.textContent='Auto · Tinta elige y recupera fallos ('+candidates.length+' modelos)';s.appendChild(auto);}[...aiWorking.keys()].forEach(m=>{const o=document.createElement('option');o.value=m;o.textContent=m+' · probado en servidor';s.appendChild(o);});}if([...s.options].some(o=>o.value===chosen))s.value=chosen;const status=$('agentAIStatus');if(status){const available=s.options.length>1;status.textContent=s.value==='__auto__'?'Enrutamiento automático activo · selección por tarea y recuperación ante fallos':s.value?'Cerebro IA privado activo · '+s.value:available?'Selecciona un modelo probado o activa Auto.':TintaProviderManager.isAuthenticated()?'Servidor privado conectado. Selecciona una conexión y prueba un modelo.':'Modo local activo. Conecta el servidor privado para usar IA externa.';status.dataset.kind=s.value?'success':'info';}}
function aiRenderModels(){const good=$('aiWorkingModels'),bad=$('aiFailedModels'),count=$('aiWorkingCount');if(count)count.textContent=String(aiWorking.size);good.replaceChildren();bad.replaceChildren();const make=(host,map,ok)=>{if(!map.size){const p=document.createElement('p');p.className='ai-empty';p.textContent=ok?'Todavía no hay modelos probados.':'Sin pruebas fallidas.';host.appendChild(p);return;}[...map.entries()].forEach(([id,detail])=>{const row=document.createElement('div');row.className='ai-model-row';const info=document.createElement('div'),title=document.createElement('strong'),sub=document.createElement('small');title.textContent=id;sub.textContent=ok?'✓ Responde a una petición de chat a través del servidor':detail;info.append(title,sub);const btn=document.createElement('button');btn.type='button';btn.className='button light';btn.textContent=ok?'Volver a probar':'Reintentar';btn.addEventListener('click',()=>aiTestOne(id));row.append(info,btn);host.appendChild(row);});};make(good,aiWorking,true);make(bad,aiFailed,false);}
function aiRenderSaved(){const host=$('aiSavedProviders');host.replaceChildren();const list=TintaProviderManager.list();if(!list.length){const p=document.createElement('p');p.className='ai-empty';p.textContent=TintaProviderManager.isAuthenticated()?'Todavía no hay proveedores guardados en el servidor.':'Conecta el servidor privado para ver tus proveedores.';host.appendChild(p);return;}list.forEach(profile=>{const row=document.createElement('div');row.className='ai-saved-row';const info=document.createElement('div'),title=document.createElement('strong'),sub=document.createElement('small');title.textContent=profile.name;sub.textContent=profile.endpoint+' · '+(profile.workingModels||[]).length+' modelos probados · '+aiNumber(profile.requestsPerDay||300)+'/día · '+aiNumber(profile.requestsPerMinute||60)+'/min';info.append(title,sub);const remove=document.createElement('button');remove.type='button';remove.className='button light';remove.textContent='Eliminar';remove.addEventListener('click',async()=>{remove.disabled=true;try{await TintaProviderManager.remove(profile.id);if(aiCurrentProfileId===profile.id){aiCurrentProfileId=null;aiWorking.clear();aiFailed.clear();aiRefreshAgentModels();aiRenderModels();}aiRenderSaved();}catch(e){aiStatus(e.message,'error');remove.disabled=false;}});row.append(info,remove);host.appendChild(row);});}
function aiOpen(){ $('aiBackendUrl').value=TintaProviderManager.getBackendUrl();aiDialog?.showModal();aiRenderSaved();if(TintaProviderManager.isAuthenticated()){aiRefreshUsage();$('aiBackendLogout').hidden=false;aiBackendStatus('Servidor privado conectado. Las claves se guardan cifradas en D1.','success');const active=TintaProviderManager.getActiveProviderId(),p=TintaProviderManager.get(active)||TintaProviderManager.list()[0];if(p)aiRestoreProfile(p);}else{$('aiBackendLogout').hidden=true;aiBackendStatus('Introduce la URL del Worker y tu contraseña de administración.','info');aiRefreshAgentModels();}}
function aiRestoreProfile(profile){if(!profile)return;aiCurrentProfileId=profile.id;TintaProviderManager.setActiveProviderId(profile.id);$('aiProviderName').value=profile.name||'Mi proveedor';$('aiProviderEndpoint').value=profile.endpoint||'';$('aiModelsPath').value=profile.modelsPath||'/models';$('aiChatPath').value=profile.chatPath||'/chat/completions';$('aiAuthMode').value=profile.authMode||'bearer';$('aiProviderRequestsPerDay').value=profile.requestsPerDay||300;$('aiProviderRequestsPerMinute').value=profile.requestsPerMinute||60;$('aiProviderKey').value='';aiLoadSessionResults(profile.id);aiRenderModels();aiRefreshAgentModels();aiStatus('Conexión seleccionada. La clave está cifrada en el servidor; escribe una nueva solo para reemplazarla.','info');}
$('aiBackendLoginForm')?.addEventListener('submit',async ev=>{ev.preventDefault();const button=$('aiBackendConnect'),password=$('aiBackendPassword').value,url=$('aiBackendUrl').value.trim();button.disabled=true;aiBackendStatus('Conectando con el servidor privado…','info');try{const r=await TintaProviderManager.login({url,password});$('aiBackendPassword').value='';$('aiBackendLogout').hidden=false;aiBackendStatus('Servidor privado conectado · sesión temporal de '+Math.round((r.expiresIn||28800)/3600)+' horas.','success');aiRenderSaved();await aiRefreshUsage();const active=TintaProviderManager.getActiveProviderId(),p=TintaProviderManager.get(active)||TintaProviderManager.list()[0];if(p)aiRestoreProfile(p);else{aiCurrentProfileId=null;aiWorking.clear();aiRefreshAgentModels();aiStatus('Servidor listo. Añade tu primer proveedor.');}}catch(e){$('aiBackendPassword').value='';aiBackendStatus(e.message,'error');}finally{button.disabled=false;}});
$('aiBackendLogout')?.addEventListener('click',()=>{TintaProviderManager.logout();aiCurrentProfileId=null;aiWorking.clear();aiFailed.clear();aiRefreshUsage();$('aiBackendLogout').hidden=true;aiBackendStatus('Sesión cerrada. Tus claves siguen cifradas en el servidor.','info');aiRefreshAgentModels();aiRenderSaved();aiStatus('Conecta el servidor para volver a cargar tus proveedores.','info');});
async function aiDiscoverAndTest(){const name=$('aiProviderName').value.trim()||'Mi proveedor',endpoint=$('aiProviderEndpoint').value.trim(),key=$('aiProviderKey').value.trim(),modelsPath=$('aiModelsPath').value.trim()||'/models',chatPath=$('aiChatPath').value.trim()||'/chat/completions',authMode=$('aiAuthMode').value,requestsPerDay=Number($('aiProviderRequestsPerDay').value),requestsPerMinute=Number($('aiProviderRequestsPerMinute').value);if(!TintaProviderManager.isAuthenticated()){aiStatus('Conecta primero el servidor privado.','error');return;}if(!endpoint){aiStatus('Introduce el endpoint del proveedor.','error');return;}if(!key&&!TintaProviderManager.get(aiCurrentProfileId)){aiStatus('Introduce la clave API para crear esta conexión.','error');return;}const id=aiCurrentProfileId||aiProfileId();aiCurrentProfileId=id;TintaProviderManager.setActiveProviderId(id);$('aiDiscoverButton').disabled=true;aiWorking.clear();aiFailed.clear();aiRenderModels();aiRefreshAgentModels();aiStatus('Guardando la conexión cifrada en el servidor…');try{const profile=await TintaProviderManager.saveProvider({id,name,endpoint,modelsPath,chatPath,authMode,requestsPerDay,requestsPerMinute},key);$('aiProviderKey').value='';aiCurrentProfileId=profile.id;const result=await TintaProviderManager.discover({providerId:id});if(!result.models.length)throw Error('El endpoint respondió, pero no publicó modelos reconocibles. Comprueba la ruta o añade el ID manualmente.');aiStatus('Encontrados '+result.models.length+' modelos. Probando desde el servidor privado…');let done=0,stoppedByLimit=false;for(const model of result.models){try{await TintaProviderManager.testModel({providerId:id,model});aiWorking.set(model,'');}catch(e){aiFailed.set(model,e.message);if(/Límite diario alcanzado|Límite por minuto alcanzado/.test(e.message))stoppedByLimit=true;}done++;aiRenderModels();aiStatus('Probados '+done+' de '+result.models.length+'. Funcionan: '+aiWorking.size+'.');if(stoppedByLimit)break;}if(stoppedByLimit)aiStatus('Se alcanzó un límite de consumo. Se detuvo el resto de las pruebas para no enviar solicitudes bloqueadas.','error');else aiStatus('Prueba terminada: '+aiWorking.size+' modelos respondieron y '+aiFailed.size+' fallaron. Las claves permanecen cifradas en el servidor.','success');aiRenderSaved();await aiRefreshUsage();}catch(e){aiStatus(e.message,'error');}finally{$('aiDiscoverButton').disabled=false;$('aiProviderKey').value='';aiRefreshAgentModels();}}
async function aiTestOne(model){if(!TintaProviderManager.isAuthenticated()||!aiCurrentProfileId){aiStatus('Conecta el servidor y selecciona una conexión.','error');return;}try{aiStatus('Probando '+model+' en el servidor…');await TintaProviderManager.testModel({providerId:aiCurrentProfileId,model});aiFailed.delete(model);aiWorking.set(model,'');aiStatus(model+' respondió correctamente.','success');}catch(e){aiWorking.delete(model);aiFailed.set(model,e.message);aiStatus(model+': '+e.message,'error');}aiRenderModels();aiRefreshAgentModels();aiRenderSaved();await aiRefreshUsage();}
async function aiSaveUsageLimits(){if(!TintaProviderManager.isAuthenticated()||!aiCurrentProfileId){aiStatus('Selecciona una conexión guardada antes de actualizar sus límites.','error');return;}const form=$('aiProviderForm');if(!form.reportValidity())return;const button=$('aiSaveUsageLimits'),key=$('aiProviderKey').value.trim();button.disabled=true;try{const profile=await TintaProviderManager.saveProvider({id:aiCurrentProfileId,name:$('aiProviderName').value.trim()||'Mi proveedor',endpoint:$('aiProviderEndpoint').value.trim(),modelsPath:$('aiModelsPath').value.trim()||'/models',chatPath:$('aiChatPath').value.trim()||'/chat/completions',authMode:$('aiAuthMode').value,requestsPerDay:Number($('aiProviderRequestsPerDay').value),requestsPerMinute:Number($('aiProviderRequestsPerMinute').value)},key);$('aiProviderKey').value='';aiRestoreProfile(profile);aiStatus('Conexión y límites guardados. No se repitieron las pruebas de modelos.','success');aiRenderSaved();await aiRefreshUsage();}catch(error){aiStatus(error.message,'error');}finally{button.disabled=false;}}
